<?php
function feedback_progress_html($f){
 $labels=FeedbackService::progressLabels();$html='<section class="feedback-review-note"><h2>处理进度（不影响审核或奖励）</h2><p>'.e($labels[$f['progress_status']]??'尚未登记处理进度').'</p><ol class="feedback-progress-timeline">';
 foreach($f['progress_events'] as $event)$html.='<li><strong>'.e($labels[$event['to_status']]??$event['to_status']).'</strong> · '.e($event['created_at']).'<p>'.nl2br(e($event['public_note'])).'</p></li>';
 return $html.'</ol></section>';
}
function register_feedback_routes($router,$pdo,$config){
 $router->get('/feedback',function()use($config,$pdo){$uid=Security::requireUser();$service=new FeedbackService($pdo);$status=isset($_GET['status'])&&is_string($_GET['status'])?$_GET['status']:'';$page=isset($_GET['page'])?(int)$_GET['page']:1;$data=$service->mine($uid,$page,20,$status);$old=$_SESSION['_feedback_old']??array();unset($_SESSION['_feedback_old']);$labels=array('pending'=>'待审核','rewarded'=>'已通过并奖励','rejected'=>'已驳回');$tabs='<nav class="pc-feedback-tabs" aria-label="反馈状态筛选">';foreach(array(''=>'全部')+$labels as $key=>$label){$tabs.='<a href="/feedback'.($key!==''?'?status='.rawurlencode($key):''). '"'.($status===$key?' class="is-active" aria-current="page"':'').'>'.e($label).'</a>';}$tabs.='</nav>';$rows='';foreach($data['items'] as $f){$rows.='<tr><td data-label="编号"><a href="/feedback/'.(int)$f['id'].'">'.e($f['feedback_no']).'</a></td><td data-label="提交时间">'.e($f['created_at']).'</td><td data-label="类型">'.($f['type']==='bug'?'BUG 反馈':'功能建议').'</td><td data-label="标题">'.e($f['subject']).'</td><td data-label="审核状态"><span class="feedback-status feedback-status-'.e($f['status']).'">'.e($labels[$f['status']]??$f['status']).'</span></td><td data-label="实际奖励">'.((int)$f['reward_cents']>0?money($f['reward_cents']):'—').'</td><td data-label="处理进度">'.e(FeedbackService::progressLabels()[$f['progress_status']]??'尚未登记').'</td><td data-label="查看"><a href="/feedback/'.(int)$f['id'].'">查看 →</a></td></tr>';}$pager='<nav class="feedback-pagination" aria-label="反馈记录分页"><span>共 '.(int)$data['total'].' 条 · 第 '.(int)$data['page'].' / '.(int)$data['pages'].' 页</span>';if($data['page']>1)$pager.='<a class="secondary-button" href="/feedback?page='.($data['page']-1).($status!==''?'&status='.rawurlencode($status):'').'">上一页</a>';if($data['page']<$data['pages'])$pager.='<a class="secondary-button" href="/feedback?page='.($data['page']+1).($status!==''?'&status='.rawurlencode($status):'').'">下一页</a>';$pager.='</nav>';$key=bin2hex(random_bytes(24));$_SESSION['_feedback_submission_keys'][$key]=1;while(count($_SESSION['_feedback_submission_keys'])>40)array_shift($_SESSION['_feedback_submission_keys']);$form='<section class="pc-feedback-form" id="feedback-form" aria-labelledby="feedback-form-title"><h2 id="feedback-form-title">提交新反馈</h2><p class="pc-field-help">请勿提交密码、密钥或订阅链接。有效性与奖励金额由管理员审核，不承诺提交即获奖。</p><form method="post" action="/feedback" data-submit-lock>'.csrf_field().'<input type="hidden" name="submission_key" value="'.e($key).'"/><label>反馈类型<select name="type"><option value="suggestion"'.(($old['type']??'')==='suggestion'?' selected':'').'>功能建议</option><option value="bug"'.(($old['type']??'')==='bug'?' selected':'').'>BUG 反馈</option></select></label><label>主题<input name="subject" maxlength="200" value="'.e($old['subject']??'').'" required></label><label>详细内容<textarea name="body" maxlength="5000" required>'.e($old['body']??'').'</textarea></label><button class="button" data-idle-label="提交反馈">提交反馈</button><p class="pc-submit-hint" hidden>正在提交，请勿重复点击。</p></form></section>';$body='<div class="feedback-page pc-feedback-page"><header class="ux-page-head"><div><h1>反馈建议</h1><p>提交 BUG 反馈或功能建议，审核通过后可获得一次性消费余额奖励。</p></div></header>'.$tabs.'<div class="pc-feedback-layout"><section class="feedback-list-card"><div class="pc-section-head"><div><h2>我的反馈记录</h2><p class="pc-muted">查看审核状态、实际奖励与独立处理进度。</p></div><span class="pc-count">共 '.(int)$data['total'].' 条</span></div><div class="table-wrap"><table><thead><tr><th>编号</th><th>提交时间</th><th>类型</th><th>标题</th><th>审核状态</th><th>实际奖励</th><th>处理进度</th><th>查看</th></tr></thead><tbody>'.($rows?:'<tr><td colspan="8"><div class="empty service-ui-empty"><h3>还没有反馈记录</h3><p>请在下方填写反馈，提交后可在这里查看审核和处理进度。</p></div></td></tr>').'</tbody></table></div>'.$pager.'</section><aside class="pc-feedback-side"><h2>反馈说明</h2><p>BUG 反馈与功能建议会由管理员审核。审核结果、奖励金额和后续处理进度分别记录，提交不代表一定获得奖励。</p><ul><li>请描述复现步骤与预期结果。</li><li>请勿填写密码、支付凭据或订阅链接。</li><li>如需订单帮助，请提交售后工单。</li></ul><a class="secondary-button" href="/tickets#new-ticket">提交售后工单</a></aside>'.$form.'</div></div>';page('反馈建议',$body,$config);});
 $router->post('/feedback',function()use($config,$pdo){$uid=Security::requireUser();post_csrf();try{$key=isset($_POST['submission_key'])?$_POST['submission_key']:'';if(!is_string($key)||!preg_match('/^[A-Za-z0-9_-]{16,80}$/D',$key)||!isset($_SESSION['_feedback_submission_keys'][$key]))throw new InvalidArgumentException('提交令牌已过期，请刷新页面。');$id=(new FeedbackService($pdo))->create($uid,isset($_POST['type'])?$_POST['type']:'',isset($_POST['subject'])?$_POST['subject']:'',isset($_POST['body'])?$_POST['body']:'',$key);unset($_SESSION['_feedback_submission_keys'][$key]);flash('success','反馈已提交，感谢你的建议。');}catch(Exception $e){$_SESSION['_feedback_old']=array();foreach(array('type','subject','body') as $field)if(isset($_POST[$field])&&is_string($_POST[$field]))$_SESSION['_feedback_old'][$field]=$_POST[$field];flash('error',$e->getMessage());}redirect('/feedback');});
 $router->get('/feedback/{id}',function($id)use($config,$pdo){$uid=Security::requireUser();try{$f=(new FeedbackService($pdo))->findMine($uid,(int)$id);}catch(Exception $e){http_response_code(404);return page('反馈不存在','<div class="empty service-ui-empty"><h1>反馈不存在或无权查看</h1><p>请返回反馈列表查看你提交的记录。</p><a class="secondary-button" href="/feedback">返回反馈列表</a></div>',$config);}$labels=array('pending'=>'待审核','rewarded'=>'已通过并奖励','rejected'=>'已驳回');$body='<div class="feedback-detail-page pc-feedback-detail"><a class="secondary-button" href="/feedback">← 返回反馈列表</a><section class="feedback-detail-card"><span class="eyebrow">FEEDBACK / '.e($f['feedback_no']).'</span><header class="ux-page-head"><div><h1>'.e($f['subject']).'</h1><p>反馈详情与处理记录</p></div></header><h2>审核与奖励</h2><p><span class="feedback-status feedback-status-'.e($f['status']).'">'.e($labels[$f['status']]??$f['status']).'</span>　'.e($f['created_at']).'</p><h2>反馈内容</h2><div class="feedback-body">'.nl2br(e($f['body'])).'</div>'.(!empty($f['admin_note'])?'<div class="feedback-review-note"><b>审核说明</b><p>'.nl2br(e($f['admin_note'])).'</p></div>':'').((int)$f['reward_cents']>0?'<div class="feedback-reward-note">奖励已入消费余额：<strong>'.e(money($f['reward_cents'])).'</strong></div>':'').feedback_progress_html($f).'</section></div>';page('反馈详情',$body,$config);});
}
